from target import prime_fib


def test_prime_fib_docstring_example_n1():
    """First prime Fibonacci (2 is both F₃ and prime). Verifies loop counts correctly to 1."""
    assert prime_fib(1) == 2


def test_prime_fib_docstring_example_n2():
    """Second prime Fibonacci (3 is F₄ and prime). Verifies correct enumeration sequence."""
    assert prime_fib(2) == 3


def test_prime_fib_docstring_example_n3():
    """Third prime Fibonacci (5 is F₅ and prime). Docstring example."""
    assert prime_fib(3) == 5


def test_prime_fib_docstring_example_n4():
    """Fourth prime Fibonacci (13 is F₇ and prime). Docstring example; skipped F₆=8 (not prime)."""
    assert prime_fib(4) == 13


def test_prime_fib_docstring_example_n5():
    """Fifth prime Fibonacci (89 is F₁₁ and prime). Tests correct handling of many non-prime Fibonacci numbers (21, 34, 55, 144)."""
    assert prime_fib(5) == 89


def test_prime_fib_boundary_n0():
    """Boundary: n=0 causes while(0 < 0) to be False immediately; loop never executes; returns unmodified b=1. Reveals missing input validation."""
    assert prime_fib(0) == 1


def test_prime_fib_boundary_negative():
    """Boundary: n=-1 causes while(0 < -1) to be False; returns b=1. Detects missing validation for n < 1."""
    assert prime_fib(-1) == 1


def test_prime_fib_boundary_n6():
    """Boundary: Sixth prime Fibonacci (233 is F₁₃ and prime). Tests boundary of documented range; requires generating Fibonacci to F₁₃."""
    assert prime_fib(6) == 233


def test_prime_fib_equivalence_class_n7():
    """Equivalence class: Seventh prime Fibonacci (1597 is F₁₇ and prime). Representative of larger n values; tests scalability and Miller-Rabin on bigger primes."""
    assert prime_fib(7) == 1597
